        }\n    }\n    \n    & .advertisement__list-item-about{\n        flex: 1 1 auto;\n        display: flex;\n        flex-direction: column;\n        gap: 10px;\n        position: relative;\n    }\n\n    & .advertisement__list-item-about-favorites {\n        cursor: pointer;\n        display: block;\n        width: 18px;\n        height: 18px;\n        background: url(../img/favorite.png) no-repeat center/cover;\n        position: absolute;\n        bottom: 0;\n        right: 0;\n    }\n\n    & .advertisement__list-item:has(.advertisement__list-item-action) .advertisement__list-item-about-favorites {\n        bottom: 25px;\n    }\n    \n    & .advertisement__list-item-title {\n        align-self: flex-start;\n        & a {\n            @include fonts($mainColor, 18px, 400);\n            overflow: hidden;\n            display: -webkit-box;\n            -webkit-line-clamp: 1;\n            -webkit-box-orient: vertical;\n            &:hover {\n                color: $colorHover;\n            }\n        }\n    }\n    \n    & .advertisement__list-item-price {\n        @include fonts($defaultColor, 16px, 400);\n    }\n    \n    & .advertisement__list-item-about-text-list {\n        & li {\n            @include fonts(#545454, 16px, 400);\n        }\n    }\n    \n    & .advertisement__list-item-action {\n        display: flex;\n        align-items: center;\n        gap: 10px;\n        align-self: flex-end;\n        & li {\n            max-width: 18px;\n            max-height: 18px;\n            & img {\n                width: 100%;\n                height: 100%;\n                object-fit: cover;\n                object-position: center;\n            }\n        }\n    }\n    & .advertisement__favorites-active {\n        background: url(../img/favorite_yes.png) no-repeat center/cover;\n    }\n}\n.second__item {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n    gap: 10px 15px;\n    flex: 1 1 auto;\n    & .advertisement__list-item {\n        display: flex;\n        flex-direction: column;\n        height: 100%;\n        justify-content: space-between;\n        gap: 10px;\n        padding: 8px;\n        border: 1px solid $gray;\n        border-radius: 7px;\n    }\n\n    & ~.vip__wrap {\n        flex: 0 0 250px;\n    }\n    \n\n    & .advertisement__list-item-img {\n        display: block;\n        & img {\n            background: #fff;\n            max-height: 140px;\n            width: 100%;\n            height: 100%;\n            object-fit: contain;\n            object-position: center;\n        }\n    }\n\n    & .advertisement__list-item-title {\n        & a {\n            display: block;\n            overflow: hidden;\n            white-space: nowrap;\n            text-overflow: ellipsis;\n            max-width: 180px;\n            @include fonts($mainColor, 16px, 400);\n            &:hover {\n                color: $colorHover;\n            }\n        }\n    }\n\n    & .advertisement__list-item-price {\n        @include fonts(#545454, 14px, 400);\n        margin: 5px 0;\n    }\n\n    & .advertisement__list-item-about-text-list {\n        display: flex;\n        flex-direction: column;\n        gap: 5px;\n\n        & li {\n            @include fonts(#545454, 14px, 400);\n            &:nth-child(1) {\n                display: none;\n            }\n            \n            &:nth-child(2) {\n                display: none;\n            }\n        }\n    }\n\n    & .advertisement__list-item-action{\n        display: flex;\n        align-items: center;\n        gap: 10px;\n        margin-top: 10px;\n        & li {\n            max-width: 18px;\n            max-height: 18px;\n            & img {\n                width: 100%;\n                height: 100%;\n                object-fit: cover;\n                object-position: center;\n            }\n        }\n    }\n\n    & .advertisement__list-item-about {\n        position: relative;\n    }\n\n    & .advertisement__list-item-about-favorites {\n        cursor: pointer;\n        display: block;\n        width: 18px;\n        height: 18px;\n        background: url(../img/favorite.png) no-repeat center/cover;\n        position: absolute;\n        bottom: 0;\n        right: 0;\n    }\n\n    & .advertisement__favorites-active {\n        background: url(../img/favorite_yes.png) no-repeat center/cover;\n    }\n}\n\n\n\n\n@media (max-width: 992px) {\n\n    .default__item{\n        flex: 1 1 auto;\n        & ~.vip__wrap {\n            flex: 1 0 250px;\n        }\n\n        & .advertisement__list-item {\n            gap: 15px;\n            flex-direction: column;\n        }\n\n        & .advertisement__list-item-img {\n            max-width: none;\n            max-height: none;\n            flex: initial;\n            & img {\n                max-height: 400px;\n            }\n        }\n\n        & .advertisement__list-item-about {\n            &::before {\n                top: initial;\n                bottom: 0;\n                right: 10px;\n                left: initial;\n            }\n        }\n    }\n    .second__item {\n        & ~.vip__wrap {\n            flex: 1 0 250px;\n        }\n    }\n}\n\n\n\n.active__item {\n    background: $activeItem;\n}",".advertisement__list {\n  flex: 1 1 680px;\n}\n\n.default__item .advertisement__list-item {\n  display: flex;\n  gap: 40px;\n  padding: 5px;\n  border-bottom: 1px solid #D4D4D4;\n}\n.default__item ~ .vip__wrap {\n  flex: 1 0 250px;\n}\n.default__item .advertisement__list-item-img {\n  display: block;\n  max-width: 180px;\n  max-height: 140px;\n  flex: 0 1 140px;\n}\n.default__item .advertisement__list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__list-item-about {\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  position: relative;\n}\n.default__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.default__item .advertisement__list-item:has(.advertisement__list-item-action) .advertisement__list-item-about-favorites {\n  bottom: 25px;\n}\n.default__item .advertisement__list-item-title {\n  align-self: flex-start;\n}\n.default__item .advertisement__list-item-title a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n.default__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.default__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  align-self: flex-end;\n}\n.default__item .advertisement__list-item-action li {\n  max-width: 18px;\n  max-height: 18px;\n}\n.default__item .advertisement__list-item-action li img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n.second__item {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 10px 15px;\n  flex: 1 1 auto;\n}\n.second__item .advertisement__list-item {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 8px;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n}\n.second__item ~ .vip__wrap {\n  flex: 0 0 250px;\n}\n.second__item .advertisement__list-item-img {\n  display: block;\n}\n.second__item .advertisement__list-item-img img {\n  background: #fff;\n  max-height: 140px;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n}\n.second__item .advertisement__list-item-title a {\n  display: block;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 180px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 16px;\n}\n.second__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.second__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n  margin: 5px 0;\n}\n.second__item .advertisement__list-item-about-text-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.second__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(1) {\n  display: none;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(2) {\n  display: none;\n}\n.second__item .advertisement__list-item-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 10px;\n}\n.second__item .advertisement__list-item-action li {\n  max-width: 18px;\n  max-height: 18px;\n}\n.second__item .advertisement__list-item-action li img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.second__item .advertisement__list-item-about {\n  position: relative;\n}\n.second__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.second__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n@media (max-width: 992px) {\n  .default__item {\n    flex: 1 1 auto;\n  }\n  .default__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n  .default__item .advertisement__list-item {\n    gap: 15px;\n    flex-direction: column;\n  }\n  .default__item .advertisement__list-item-img {\n    max-width: none;\n    max-height: none;\n    flex: initial;\n  }\n  .default__item .advertisement__list-item-img img {\n    max-height: 400px;\n  }\n  .default__item .advertisement__list-item-about::before {\n    top: initial;\n    bottom: 0;\n    right: 10px;\n    left: initial;\n  }\n  .second__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n}\n.active__item {\n  background: #FFFFCA;\n}\n\n.store {\n  margin: 20px 0;\n  display: flex;\n  border: 1px solid #D4D4D4;\n  border-radius: 0 0 5px 5px;\n}\n\n.store__about {\n  flex: 1 1 auto;\n  border-right: 1px solid #D4D4D4;\n}\n.store__about h2 {\n  padding: 15px 15px 50px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  border-bottom: 1px solid #D4D4D4;\n  background: #f1f1d8;\n}\n.store__about p {\n  padding: 15px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  word-break: break-word;\n}\n\n.store__info {\n  padding: 8px;\n  flex: 0 0 340px;\n}\n\n.store__info-img {\n  max-width: 140px;\n  margin-bottom: 15px;\n}\n.store__info-img img {\n  max-height: 93px;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n}\n\n.store__info-district {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n\n.store__info-text {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  word-break: break-word;\n  margin-bottom: 10px;\n}\n\n.store__send-email {\n  margin: 10px 0;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.store__send-email::before {\n  content: \"\";\n  display: block;\n  width: 15px;\n  height: 15px;\n  background: url(../img/icons/email.gif) no-repeat center/cover;\n}\n.store__send-email:hover {\n  color: red;\n}\n\n.store__info-phone {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.store__info-phone::before {\n  content: \"\";\n  display: block;\n  width: 15px;\n  height: 15px;\n  background: url(../img/icons/telefon.gif) no-repeat center/cover;\n}\n\n.store__info-site {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.store__info-site::before {\n  content: \"\";\n  display: block;\n  width: 15px;\n  height: 15px;\n  background: url(../img/icons/site.png) no-repeat center/cover;\n}\n\n@media (max-width: 992px) {\n  .store {\n    flex-direction: column;\n  }\n  .store__info {\n    flex: initial;\n  }\n  .store__about {\n    border-right: none;\n    border-bottom: 1px solid #D4D4D4;\n  }\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);","@import \"./variables\";\n@import \"./mixins\";\n@import \"./advertisementItem\";\n\n.store {\n  margin: 20px 0;\n  display: flex;\n  border: 1px solid $gray;\n  border-radius: 0 0 5px 5px;\n}\n\n.store__about {\n  flex: 1 1 auto;\n  border-right: 1px solid $gray;\n  & h2 {\n    padding: 15px 15px 50px;\n    @include fonts($defaultColor, 18px, 600);\n    border-bottom: 1px solid $gray;\n    background: #f1f1d8;\n  }\n\n  & p {\n    padding: 15px;\n    @include fonts($defaultColor, 14px, 400);\n    word-break: break-word;\n  }\n}\n\n.store__info {\n  padding: 8px;\n  flex: 0 0 340px;\n}\n\n.store__info-img {\n  max-width: 140px;\n  margin-bottom: 15px;\n  & img {\n    max-height: 93px;\n    width: 100%;\n    height: 100%;\n    object-fit: contain;\n    object-position: center;\n  }\n}\n\n.store__info-district {\n  @include fonts($defaultColor, 16px, 400);\n  margin-bottom: 10px;\n}\n\n.store__info-text {\n  @include fonts($defaultColor, 14px, 400);\n  word-break: break-word;\n  margin-bottom: 10px;\n}\n\n.store__send-email {\n  margin: 10px 0;\n  @include fonts($mainColor, 14px, 400);  \n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  &::before {\n    content: \"\";\n    display: block;\n    width: 15px;\n    height: 15px;\n    background: url(../img/icons/email.gif) no-repeat center/cover;\n  }\n  &:hover {\n    color: $colorHover;\n  }\n}\n\n.store__info-phone {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  &::before {\n    content: \"\";\n    display: block;\n    width: 15px;\n    height: 15px;\n    background: url(../img/icons/telefon.gif) no-repeat center/cover;\n  }\n}\n\n.store__info-site {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  &::before {\n    content: \"\";\n    display: block;\n    width: 15px;\n    height: 15px;\n    background: url(../img/icons/site.png) no-repeat center/cover;\n  }\n}\n\n@media (max-width:992px) {\n  .store {\n    flex-direction: column;\n  }\n\n  .store__info {\n    flex: initial;\n  }\n\n  .store__about {\n    border-right: none;\n    border-bottom: 1px solid $gray;\n  }\n}"]}one;\n    border-bottom: 1px solid $gray;\n  }\n}"]}